const body = $input.first().json.body || $input.first().json;
const jobs = body.jobs || [];
const resumeText = body.resumeText || '';
const profile = body.profile || {};

if (!jobs.length) throw new Error('No jobs provided');
if (!resumeText) throw new Error('No resumeText provided');

return jobs.map(job => ({
  json: {
    jobId:      job.id,
    jobTitle:   job.title,
    company:    job.co,
    jobUrl:     job.url,
    resumeText,
    profile
  }
}));

const allJina = $input.all();
const allPrev = $('Split Jobs').all();

return allJina.map((jinaItem, i) => {
  const jinaResp = jinaItem.json;
  const prev = (allPrev[i] || allPrev[0]).json;

  let jdText = '';
  if (typeof jinaResp === 'string') {
    jdText = jinaResp;
  } else if (jinaResp.data && typeof jinaResp.data === 'string') {
    jdText = jinaResp.data;
  } else {
    jdText = JSON.stringify(jinaResp);
  }

  jdText = jdText.substring(0, 3000).trim();

  if (!jdText) {
    jdText = `Job Title: ${prev.jobTitle} at ${prev.company}. No additional description available.`;
  }

  return {
    json: {
      ...prev,
      jobDescription: jdText
    }
  };
});

