const allOpenAI = $input.all();
const allPrev = $('Extract Job Description').all();

return allOpenAI.map((openaiItem, i) => {
  const openaiResp = openaiItem.json;
  const prev = (allPrev[i] || allPrev[0]).json;

  let resumeData;
  try {
    const content = openaiResp.choices[0].message.content;
    resumeData = typeof content === 'string' ? JSON.parse(content) : content;
  } catch(e) {
    throw new Error('Failed to parse OpenAI response for job ' + i + ': ' + e.message);
  }

  return {
    json: {
      jobId:    prev.jobId,
      jobTitle: prev.jobTitle,
      company:  prev.company,
      resumeData
    }
  };
});

const allDocx = $input.all();
const allPrev = $('Parse Tailored Resume').all();

return allDocx.map((docxItem, i) => {
  const docxResp = docxItem.json;
  const prev = (allPrev[i] || allPrev[0]).json;

  return {
    json: {
      jobId:      prev.jobId,
      jobTitle:   prev.jobTitle,
      company:    prev.company,
      docxBase64: docxResp.docxBase64,
      fileName:   docxResp.fileName
    }
  };
});
